using System;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.InputSystem;
using TMPro;
using DG.Tweening;
using LWS.TruckSports;
namespace LWS.TruckHockey {
public enum HockeyScreen {Setup,Join,Match,Pause,Help,Settings,Confirm,Disconnect,Result,InputCheck,Keys}
public sealed class HockeyMenus:SportsMenuView {
 public HockeyMatch match;public HockeyScreen Screen=HockeyScreen.Setup;public TMP_InputField name1,name2;public TMP_InputField[] names;public TMP_Text[] sourceLabels,levelLabels,inputLabels,keyLabels;
 public TMP_Text modeText,soloText,color1Text,color2Text,difficultyText,durationText,setupInfo,joinInfo,disconnectInfo,scoreText,clockText,teamText,messageText,controlsText,resultText,helpText,confirmText,keyInfo;
 public TMP_Text orangeTeamText;public GameObject hud;public RectTransform resultTitle;public RectTransform[] confetti;public Color[] palette={new Color(.15f,.8f,1),new Color(1,.55f,.13f),new Color(.85f,.25f,.7f),new Color(.6f,1,.3f),new Color(.9f,.85f,.25f)};
 int color1,color2=1,joinVersion=-1,rebindSlot=-1,rebindKey;HockeyScreen returnScreen;string confirmation;bool disconnectReleased;int disconnectGateFrame;float nextHud;SportsMenuAction[][] actions;readonly List<Tween> tweens=new List<Tween>();
 const string Controls="3v3 • All six trucks may hit the puck at any time. Drive into it; no shooting, passing or boost button.\n\nKeyboard Chaos: W/A/S/D • T/F/G/H • I/J/K/L • arrows • Z/X/C/V • numpad 8/4/5/6. The back key brakes forward motion, then reverses; forward similarly brakes reverse motion. Keys are editable in Keyboard Bindings. Escape is reserved.\n\nWhole controller: left stick steer • RT forward • LT brake/reverse.\nShared controller: left stick and right stick each drive one truck. X steers, Y brakes/reverses; each truck uses its own forward direction. Start pauses.\n\nPause > Recover slot recovers only that truck. Whole controller: North also recovers. Controllers belong to one whole slot or two different stick slots.\n\nFull goal crossing scores for the attacking TEAM, including own goals. Regulation ties enter sudden death. Rematch keeps all six slots and swaps ends. No offsides, icing or penalties.";
 protected override void Start(){base.Start();actions=new SportsMenuAction[pages.Length][];for(int i=0;i<pages.Length;i++)if(pages[i]!=null)actions[i]=pages[i].GetComponentsInChildren<SportsMenuAction>(true);for(int i=0;i<6;i++){int slot=i;names[i].onEndEdit.AddListener(v=>{match.players[slot].name=string.IsNullOrWhiteSpace(v)?"Player "+(slot+1):v.Trim();match.SaveSetup();match.Dirty();RefreshSetup();});}Show(Screen);}
 public void Show(HockeyScreen screen){Screen=screen;if(screen==HockeyScreen.Disconnect){disconnectReleased=false;disconnectGateFrame=Time.frameCount;}feedback.StopMotors();if(screen!=HockeyScreen.Result)ClearCelebration();hud.SetActive(screen==HockeyScreen.Match);base.Show((int)screen);if(screen==HockeyScreen.Setup)RefreshSetup();if(screen==HockeyScreen.Join||screen==HockeyScreen.Disconnect){joinVersion=-1;RefreshJoin();}if(screen==HockeyScreen.Help)helpText.text=Controls;if(screen==HockeyScreen.Settings)SettingsText();if(screen==HockeyScreen.Keys)RefreshKeys();if(screen==HockeyScreen.Result){resultText.text=match.TeamName(match.rules.Winner)+" WINS\n"+match.rules.Score[0]+" : "+match.rules.Score[1]+"\n"+Roster(0)+"\n"+Roster(1)+(match.rules.Overtime?"\nSUDDEN-DEATH VICTORY":"\nREGULATION COMPLETE");resultText.color=match.players[match.rules.Winner*3].color;}Focus();SelectJoinPrimary();RefreshHUD();}
 string Roster(int team){int p=team*3;return match.PlayerName(p)+" • "+match.PlayerName(p+1)+" • "+match.PlayerName(p+2);}
 public override void Action(string key){if(Screen==HockeyScreen.Disconnect&&!DisconnectConfirm())return;base.Action(key);if(key.StartsWith("source")){match.CycleSource(int.Parse(key.Substring(6)));RefreshSetup();return;}if(key.StartsWith("level")){int slot=int.Parse(key.Substring(5));match.players[slot].difficulty=(HockeyDifficulty)(((int)match.players[slot].difficulty+1)%3);match.SaveSetup();RefreshSetup();return;}if(key.StartsWith("reassign")){match.Unassign(int.Parse(key.Substring(8)));return;}if(key.StartsWith("recover")){int slot=int.Parse(key.Substring(7));match.trucks[slot].Recover(true);return;}if(key.StartsWith("key_")){var parts=key.Split('_');rebindSlot=int.Parse(parts[1]);rebindKey=int.Parse(parts[2]);keyInfo.text="Press the new gameplay key for slot "+(rebindSlot+1)+". Escape cancels; active duplicate keys are rejected.";UnityEngine.EventSystems.EventSystem.current.SetSelectedGameObject(null);return;}
 switch(key){case "mode":match.mode=(HockeyMode)(((int)match.mode+1)%7);match.Configure();match.SaveSetup();RefreshSetup();break;case "solo":match.soloController=!match.soloController;match.Configure();RefreshSetup();break;case "color1":case "color2":int team=key=="color1"?0:1;int c=team==0?(color1+1)%palette.Length:(color2+1)%palette.Length;if(c==(team==0?color2:color1))c=(c+1)%palette.Length;if(team==0)color1=c;else color2=c;for(int i=team*3;i<team*3+3;i++)match.players[i].color=palette[c];match.SaveSetup();RefreshSetup();break;case "difficulty":match.difficulty=(HockeyDifficulty)(((int)match.difficulty+1)%3);for(int i=0;i<6;i++)if(match.IsAI(i))match.players[i].difficulty=match.difficulty;match.SaveSetup();RefreshSetup();break;case "duration":match.durationMinutes=match.durationMinutes==2?3:match.durationMinutes==3?5:2;match.SaveSetup();RefreshSetup();break;case "start":match.StartMatch();break;case "resume":match.Resume();break;case "inputcheck":returnScreen=Screen;Show(HockeyScreen.InputCheck);break;case "keys":returnScreen=Screen;Show(HockeyScreen.Keys);break;case "controls":returnScreen=Screen;Show(HockeyScreen.Help);break;case "settings":returnScreen=Screen;Show(HockeyScreen.Settings);break;case "back":Back();break;case "restart":confirmation="restart";confirmText.text="RESTART MATCH?\nScores and clock reset. All six participants and rink ends are retained.";Show(HockeyScreen.Confirm);break;case "front":if(match.InMatch&&match.rules.Phase!=HockeyPhase.Finished){confirmation="front";confirmText.text="RETURN TO SPORT SELECTION?\nThis match will be abandoned.";Show(HockeyScreen.Confirm);}else{match.SaveSetup();SportsNavigation.FrontEnd();}break;case "yes":if(confirmation=="restart")match.Restart();else{match.SaveSetup();SportsNavigation.FrontEnd();}break;case "no":Show(HockeyScreen.Pause);break;case "rematch":match.StartMatch(true);break;case "setup":match.ChangeSetup();break;}}
 public void Back(){if(rebindSlot>=0){rebindSlot=-1;RefreshKeys();Focus();return;}if(Screen==HockeyScreen.Setup){match.SaveSetup();SportsNavigation.FrontEnd();}else if(Screen==HockeyScreen.Join)match.ChangeSetup();else if(Screen==HockeyScreen.Help||Screen==HockeyScreen.Settings||Screen==HockeyScreen.InputCheck||Screen==HockeyScreen.Keys)Show(returnScreen);else if(Screen==HockeyScreen.Confirm)Show(HockeyScreen.Pause);else if(Screen==HockeyScreen.Pause||Screen==HockeyScreen.Disconnect)match.Resume();}
 public void RefreshSetup(){if(names==null)return;modeText.text=new[]{"1 HUMAN + 5 AI","KEYBOARD CHAOS • 6 HUMANS","6 WHOLE CONTROLLERS","KEYBOARD + CONTROLLER + 4 AI","6 AI • SPECTATE","3 SHARED CONTROLLERS","CUSTOM MIX"}[(int)match.mode];durationText.text="Duration: "+match.durationMinutes+" MINUTES";for(int i=0;i<6;i++){var p=match.players[i];names[i].SetTextWithoutNotify(p.name);sourceLabels[i].text=p.source==HockeySource.Keyboard?"KEYBOARD • "+p.forward+"/"+p.left+"/"+p.back+"/"+p.right:p.source.ToString().ToUpper();levelLabels[i].text=p.source==HockeySource.AI?p.difficulty.ToString().ToUpper():"HUMAN";levelLabels[i].transform.parent.gameObject.SetActive(p.source==HockeySource.AI);}color1Text.text="BLUE TEAM COLOR";color2Text.text="ORANGE TEAM COLOR";color1Text.color=match.players[0].color;color2Text.color=match.players[3].color;setupInfo.text=match.ValidateOwnership(out string reason)?"0–6 humans • click each source to choose AI, keyboard, whole pad or a shared stick.\nNorth joins empty pad slots. Shared sticks can belong to the same controller.":reason;Focus();}
 public void RefreshJoin(){if(Screen!=HockeyScreen.Join&&Screen!=HockeyScreen.Disconnect||actions==null||joinVersion==match.SetupVersion)return;joinVersion=match.SetupVersion;bool valid=match.ValidateOwnership(out string reason),ready=valid&&match.DevicesReady;var text=new System.Text.StringBuilder("North / Y / Triangle joins empty pad slots. Each input source has one owner.\n\n");for(int i=0;i<6;i++){var p=match.players[i];text.Append(i<3?"B":"O").Append(i%3+1).Append(" • ").Append(p.name).Append(": ").Append(p.source);if(p.controller)text.Append(match.Ready(i)?" • "+p.pad.displayName+" ID "+p.pad.deviceId:" • DISCONNECTED / NOT JOINED");text.Append('\n');}text.Append("\n").Append(valid?"Whole pad = one truck; left / right sticks = separate trucks.\nReconnect the same device, or explicitly Reassign. Resume requires fresh input.":reason);joinInfo.text=disconnectInfo.text=text.ToString();foreach(int page in new[]{(int)HockeyScreen.Join,(int)HockeyScreen.Disconnect})foreach(var a in actions[page]){if(a.action.StartsWith("reassign"))a.gameObject.SetActive(match.players[int.Parse(a.action.Substring(8))].controller);if(a.action=="start"||a.action=="resume"){a.button.isInteractable=ready;a.GetComponent<UnityEngine.UI.Button>().interactable=ready;}}Focus();SelectJoinPrimary();}
 void RefreshKeys(){for(int i=0;i<6;i++){var p=match.players[i];keyLabels[i*4].text=p.forward.ToString();keyLabels[i*4+1].text=p.left.ToString();keyLabels[i*4+2].text=p.back.ToString();keyLabels[i*4+3].text=p.right.ToString();}keyInfo.text="Click a key to rebind: FORWARD / LEFT / BRAKE–REVERSE / RIGHT.\nEscape is reserved. Duplicate ACTIVE keyboard gameplay keys are rejected."; }
 string RosterLines(int team){int start=team*3;string text="";for(int i=0;i<3;i++)text+=(i==0?"":"\n")+(team==0?"B":"O")+(i+1)+" • "+match.players[start+i].name+(i==0?" • "+(match.rules.DefendingSign(team)<0?"LEFT":"RIGHT"):"");return text;}
 public void RefreshHUD(){if(!match.InMatch)return;scoreText.text="<color=#"+ColorUtility.ToHtmlStringRGB(match.players[0].color)+">BLUE  "+match.rules.Score[0]+"</color>   :   <color=#"+ColorUtility.ToHtmlStringRGB(match.players[3].color)+">"+match.rules.Score[1]+"  ORANGE</color>";clockText.text=match.rules.Overtime?"OVERTIME • SUDDEN DEATH":(Mathf.CeilToInt(match.rules.Remaining)/60).ToString("00")+":"+(Mathf.CeilToInt(match.rules.Remaining)%60).ToString("00");if(orangeTeamText==null){teamText.text=Roster(0)+" • defends "+(match.rules.DefendingSign(0)<0?"LEFT":"RIGHT")+"\n"+Roster(1)+" • defends "+(match.rules.DefendingSign(1)<0?"LEFT":"RIGHT");}else{teamText.text=RosterLines(0);orangeTeamText.text=RosterLines(1);teamText.color=match.players[0].color;orangeTeamText.color=match.players[3].color;}var phase=match.rules.Phase;messageText.text=phase==HockeyPhase.Pregame||phase==HockeyPhase.Faceoff?((phase==HockeyPhase.Faceoff&&match.Notice.StartsWith("PUCK RECOVERY"))?"PUCK RECOVERY • FAIR FACEOFF  ":"FACEOFF  ")+Mathf.Max(1,Mathf.CeilToInt(match.rules.PhaseTimer)):match.Notice;controlsText.text="3v3 • Opposite throttle brakes, then reverses • Esc / Start pauses\nPause > Recover your slot • No shooting / pass / boost"; }
 public void ResetReconnectInput(Gamepad pad){menuInput.Forget(pad);disconnectReleased=false;disconnectGateFrame=Time.frameCount;}
 void SelectJoinPrimary(){if(actions==null||(Screen!=HockeyScreen.Join&&Screen!=HockeyScreen.Disconnect)||!match.DevicesReady||UnityEngine.EventSystems.EventSystem.current==null)return;string key=Screen==HockeyScreen.Join?"start":"resume";foreach(var action in actions[(int)Screen])if(action.action==key){UnityEngine.EventSystems.EventSystem.current.SetSelectedGameObject(action.gameObject);break;}}
 bool DisconnectConfirm(){if(!disconnectReleased)return false;if(SportsDeviceInput.KeyDown(Key.Enter)||SportsDeviceInput.KeyDown(Key.Space)||(Mouse.current!=null&&Mouse.current.leftButton.wasReleasedThisFrame))return true;foreach(var pad in Gamepad.all)if(pad.buttonSouth.wasPressedThisFrame)return true;return false;}
 protected override void Update(){base.Update();if(Screen==HockeyScreen.Disconnect&&!disconnectReleased&&Time.frameCount>disconnectGateFrame){bool neutral=!SportsDeviceInput.KeyHeld(Key.Enter)&&!SportsDeviceInput.KeyHeld(Key.Space)&&(Mouse.current==null||(!Mouse.current.leftButton.isPressed&&!Mouse.current.leftButton.wasReleasedThisFrame));foreach(var pad in Gamepad.all)neutral&=!pad.buttonSouth.isPressed&&pad.leftStick.ReadValue().magnitude<.16f&&pad.rightStick.ReadValue().magnitude<.16f;if(neutral){disconnectReleased=true;SelectJoinPrimary();}}if(Screen==HockeyScreen.Keys&&rebindSlot>=0&&Keyboard.current!=null){foreach(var k in Keyboard.current.allKeys)if(k.wasPressedThisFrame){if(k.keyCode==Key.Escape){Back();return;}var p=match.players[rebindSlot];Key old=rebindKey==0?p.forward:rebindKey==1?p.left:rebindKey==2?p.back:p.right;SetKey(p,rebindKey,k.keyCode);if(!match.ValidateOwnership(out string reason)){SetKey(p,rebindKey,old);keyInfo.text=reason;return;}match.mode=HockeyMode.Custom;match.SaveSetup();match.Dirty();rebindSlot=-1;RefreshKeys();Focus();return;}}
 foreach(var p in Gamepad.all)if(menuInput.Down(p,8)&&Screen!=HockeyScreen.Match){Back();break;}if(Time.unscaledTime<nextHud)return;nextHud=Time.unscaledTime+.1f;if(Screen==HockeyScreen.InputCheck)for(int i=0;i<6;i++){var p=match.players[i];Vector2 v=match.IsAI(i)||!match.Ready(i)?Vector2.zero:match.DriveFor(i);inputLabels[i].text=(i<3?"B":"O")+(i%3+1)+" • "+p.name+" • "+p.source+" • steer "+v.x.ToString("F2")+" / throttle "+v.y.ToString("F2");inputLabels[i].color=v.sqrMagnitude>.01f?Color.yellow:Color.white;}RefreshHUD();}
 static void SetKey(HockeyPlayer p,int index,Key value){if(index==0)p.forward=value;else if(index==1)p.left=value;else if(index==2)p.back=value;else p.right=value;}
 void OnDisable(){ClearCelebration();} public void Celebrate(Color color,bool winner){ClearCelebration();int count=winner?confetti.Length:confetti.Length/2;for(int i=0;i<count;i++){var r=confetti[i];r.gameObject.SetActive(true);r.GetComponent<UnityEngine.UI.Image>().color=i%3==0?Color.white:color;Vector2 from=new Vector2((i%2==0?-1:1)*(330+i%8*18),150);r.anchoredPosition=from;var to=from+new Vector2((i%2==0?-1:1)*35,-190-i%4*20);tweens.Add(DOTween.To(()=>r.anchoredPosition,v=>r.anchoredPosition=v,to,winner?1.5f:1).SetEase(Ease.OutQuad).SetUpdate(true).OnComplete(()=>r.gameObject.SetActive(false)));}if(winner)tweens.Add(resultTitle.DOScale(1.06f,.18f).SetLoops(2,LoopType.Yoyo).SetUpdate(true));}
 public void ClearCelebration(){foreach(var t in tweens)if(t!=null&&t.IsActive())t.Kill();tweens.Clear();if(confetti!=null)foreach(var c in confetti)if(c!=null)c.gameObject.SetActive(false);if(resultTitle!=null)resultTitle.localScale=Vector3.one;}

}
}
